CREATE OR REPLACE FUNCTION public.finalize_customer_handoff(p_dilmart_user_id uuid, p_store_customer_id uuid, p_identity_outcome text, p_link_method text, p_link_status text, p_identity_assurance text, p_reuse_existing boolean, p_conflict_reason text, p_code_hash text, p_state_hash text, p_assertion_jti text, p_target_path text, p_source_surface text, p_campaign text, p_code_ttl_seconds integer, p_kid text, p_email text, p_phone_verified_at timestamp with time zone, p_email_verified_at timestamp with time zone, p_request_id uuid)
 RETURNS TABLE(status text, error_code text, handoff_id uuid, expires_at timestamp with time zone, linked_profile_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_link              public.store_linked_profiles%ROWTYPE;
  v_found             BOOLEAN := FALSE;
  v_linked_profile_id UUID;
  v_effective_customer UUID;
  v_actual_customer   UUID;
  v_handoff_id        UUID;
  v_expires_at        TIMESTAMPTZ;
  v_constraint        TEXT;
BEGIN
  -- B3: the code TTL is EXACTLY 120s for this implementation, or fail.
  IF p_code_ttl_seconds IS DISTINCT FROM 120 THEN
    RAISE EXCEPTION 'handoff code ttl must be exactly 120 seconds' USING ERRCODE = 'check_violation';
  END IF;

  -- B2: serialize all finalizations for the SAME DilMart user (transaction-scoped advisory lock) so
  -- concurrent calls resolve deterministically rather than racing on the store_customer_id partial-unique
  -- index (which ON CONFLICT(DilMart_user_id) does not arbitrate). The second caller then observes the
  -- first's committed link under the FOR UPDATE read below.
  PERFORM pg_advisory_xact_lock(hashtext('customer_handoff_finalize'), hashtext(p_DilMart_user_id::text));

  -- Lock the existing identity link for this DilMart user and recheck under serialization.
  SELECT * INTO v_link FROM public.store_linked_profiles WHERE DilMart_user_id = p_DilMart_user_id FOR UPDATE;
  v_found := FOUND;

  IF p_identity_outcome = 'LINKED' THEN
    IF p_reuse_existing THEN
      -- EXISTING_LINK: the locked row must STILL be a customer-compatible LINKED row owning exactly
      -- p_store_customer_id; anything else fails closed.
      IF NOT v_found
         OR upper(coalesce(v_link.DilMart_role, '')) <> 'CUSTOMER'
         OR upper(coalesce(v_link.link_status, '')) <> 'LINKED'
         OR v_link.store_customer_id IS DISTINCT FROM p_store_customer_id THEN
        RETURN QUERY SELECT 'ERROR', 'IDENTITY_BLOCKED', NULL::UUID, NULL::TIMESTAMPTZ, NULL::UUID;
        RETURN;
      END IF;
      v_linked_profile_id := v_link.id;
      v_effective_customer := v_link.store_customer_id;  -- the LOCKED value is authoritative
      UPDATE public.store_linked_profiles
         SET last_handoff_at = clock_timestamp(), updated_at = now()
       WHERE id = v_link.id;
    ELSE
      -- New / verified-candidate link. A pre-existing row must be customer-compatible, not blocked/revoked,
      -- and must not already own a DIFFERENT store customer.
      IF v_found THEN
        IF upper(coalesce(v_link.DilMart_role, '')) NOT IN ('', 'CUSTOMER')
           OR upper(coalesce(v_link.link_status, '')) IN ('BLOCKED', 'REVOKED')
           OR (v_link.store_customer_id IS NOT NULL AND v_link.store_customer_id IS DISTINCT FROM p_store_customer_id) THEN
          RETURN QUERY SELECT 'ERROR', 'IDENTITY_BLOCKED', NULL::UUID, NULL::TIMESTAMPTZ, NULL::UUID;
          RETURN;
        END IF;
      END IF;

      -- Upsert, then re-verify the ACTUAL persisted customer equals the intended one. A concurrent request
      -- that linked a different customer first makes COALESCE keep the other value → roll back + BLOCK.
      BEGIN
        INSERT INTO public.store_linked_profiles
          (DilMart_user_id, DilMart_role, store_customer_id, segment, source_app, email,
           link_status, link_method, identity_assurance, phone_verified_at, email_verified_at,
           linked_at, last_handoff_at, last_synced_at, updated_at)
        VALUES
          (p_DilMart_user_id, 'CUSTOMER', p_store_customer_id, 'DilMart_APP_CUSTOMER', 'customer_app', p_email,
           p_link_status, p_link_method, p_identity_assurance, p_phone_verified_at, p_email_verified_at,
           clock_timestamp(), clock_timestamp(), now(), now())
        ON CONFLICT (DilMart_user_id) DO UPDATE
          SET store_customer_id  = COALESCE(public.store_linked_profiles.store_customer_id, EXCLUDED.store_customer_id),
              link_status        = EXCLUDED.link_status,
              link_method        = EXCLUDED.link_method,
              identity_assurance = EXCLUDED.identity_assurance,
              email              = COALESCE(EXCLUDED.email, public.store_linked_profiles.email),
              phone_verified_at  = COALESCE(EXCLUDED.phone_verified_at, public.store_linked_profiles.phone_verified_at),
              email_verified_at  = COALESCE(EXCLUDED.email_verified_at, public.store_linked_profiles.email_verified_at),
              linked_at          = COALESCE(public.store_linked_profiles.linked_at, EXCLUDED.linked_at),
              last_handoff_at    = clock_timestamp(),
              updated_at         = now()
        RETURNING id, store_customer_id INTO v_linked_profile_id, v_actual_customer;

        IF v_actual_customer IS DISTINCT FROM p_store_customer_id THEN
          RAISE EXCEPTION 'store customer ownership conflict';  -- rolls back this upsert (nested savepoint)
        END IF;
      EXCEPTION WHEN raise_exception THEN
        IF SQLERRM LIKE '%ownership conflict%' THEN
          RETURN QUERY SELECT 'ERROR', 'IDENTITY_BLOCKED', NULL::UUID, NULL::TIMESTAMPTZ, NULL::UUID;
          RETURN;
        END IF;
        RAISE;
      END;

      v_effective_customer := v_actual_customer;
    END IF;
  ELSE
    -- LINK_REQUIRED / BLOCKED: never create, re-own, OR mutate a link row (task C3). The conflict state
    -- lives only in the handoff row (identity_outcome/status) and the audit event (error_code + metadata);
    -- a Barber/OWNER linked-profile row is left byte-for-byte semantically unchanged.
    v_linked_profile_id := NULL;
    v_effective_customer := NULL;
  END IF;

  INSERT INTO public.DilMart_customer_handoffs AS h
    (code_hash, state_hash, assertion_jti, DilMart_user_id, linked_profile_id, store_customer_id,
     target_path, source_surface, campaign, status, identity_outcome, expires_at)
  VALUES
    (p_code_hash, p_state_hash, p_assertion_jti, p_DilMart_user_id,
     CASE WHEN p_identity_outcome = 'LINKED' THEN v_linked_profile_id ELSE NULL END,
     CASE WHEN p_identity_outcome = 'LINKED' THEN v_effective_customer ELSE NULL END,
     p_target_path, p_source_surface, p_campaign,
     CASE WHEN p_identity_outcome = 'LINKED' THEN 'PENDING' ELSE p_identity_outcome END,
     p_identity_outcome,
     clock_timestamp() + make_interval(secs => p_code_ttl_seconds))
  RETURNING h.id, h.expires_at INTO v_handoff_id, v_expires_at;

  -- B8: the atomic PREPARED audit carries the API request id.
  INSERT INTO public.DilMart_customer_handoff_audit_events
    (request_id, handoff_id, linked_profile_id, event_type, status, source_surface, campaign, error_code, metadata)
  VALUES
    (p_request_id, v_handoff_id,
     CASE WHEN p_identity_outcome = 'LINKED' THEN v_linked_profile_id ELSE NULL END,
     'HANDOFF_PREPARED', p_identity_outcome, p_source_surface, p_campaign,
     CASE WHEN p_identity_outcome IN ('LINK_REQUIRED','BLOCKED') THEN p_identity_outcome ELSE NULL END,
     jsonb_build_object('kid', p_kid, 'linkMethod', p_link_method, 'conflictReason', p_conflict_reason));

  RETURN QUERY SELECT 'OK', NULL::TEXT, v_handoff_id, v_expires_at, v_linked_profile_id;
  RETURN;

EXCEPTION
  WHEN unique_violation THEN
    GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
    IF v_constraint = 'uq_store_linked_profiles_store_customer_id' THEN
      RETURN QUERY SELECT 'ERROR', 'IDENTITY_BLOCKED', NULL::UUID, NULL::TIMESTAMPTZ, NULL::UUID;
    ELSE
      RETURN QUERY SELECT 'ERROR', 'HANDOFF_INVALID', NULL::UUID, NULL::TIMESTAMPTZ, NULL::UUID;
    END IF;
    RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.logout_federated_session(p_refresh_token_hash text, p_request_id uuid)
 RETURNS TABLE(status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_fam_id UUID;
  v_fam public.store_federated_session_families%ROWTYPE;
  v_tok public.store_federated_refresh_tokens%ROWTYPE;
BEGIN
  SELECT session_family_id INTO v_fam_id FROM public.store_federated_refresh_tokens WHERE token_hash = p_refresh_token_hash;
  IF v_fam_id IS NOT NULL THEN
    SELECT * INTO v_fam FROM public.store_federated_session_families WHERE id = v_fam_id FOR UPDATE;
    IF FOUND THEN
      SELECT * INTO v_tok FROM public.store_federated_refresh_tokens WHERE token_hash = p_refresh_token_hash FOR UPDATE;
      IF FOUND
         AND v_tok.session_family_id = v_fam.id
         AND v_tok.used_at IS NULL
         AND v_tok.revoked_at IS NULL
         AND v_tok.expires_at > clock_timestamp()
         AND v_fam.status = 'ACTIVE'
         AND v_fam.revoked_at IS NULL
         AND v_fam.absolute_expires_at > clock_timestamp()
         AND (v_fam.last_used_at + make_interval(secs => 2592000)) > clock_timestamp() THEN
        UPDATE public.store_federated_session_families
           SET status = 'REVOKED', revoked_at = clock_timestamp(), revoke_reason = 'USER_LOGOUT',
               session_version = store_federated_session_families.session_version + 1, updated_at = now()
         WHERE id = v_fam.id;
        UPDATE public.store_federated_refresh_tokens SET revoked_at = clock_timestamp()
          WHERE session_family_id = v_fam.id AND revoked_at IS NULL;
        INSERT INTO public.store_federated_session_audit_events
          (request_id, session_family_id, linked_profile_id, store_customer_id, event_type, status)
        VALUES (p_request_id, v_fam.id, v_fam.linked_profile_id, v_fam.store_customer_id, 'FEDERATED_SESSION_LOGOUT', 'REVOKED');
      END IF;
    END IF;
  END IF;
  -- Idempotent + no oracle: always report logged_out.
  RETURN QUERY SELECT 'logged_out'; RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.provision_dilmart_federated_customer(p_dilmart_user_id uuid, p_federated_id text)
 RETURNS TABLE(store_customer_id uuid, error_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_email TEXT := 'DilMart-federated+' || p_federated_id || '@federated.DilMart.internal';
  v_id    UUID;
  v_other UUID;
BEGIN
  IF p_federated_id IS NULL OR p_federated_id !~ '^[A-Za-z0-9_-]{16,120}$' THEN
    RAISE EXCEPTION 'invalid federated_id' USING ERRCODE = 'check_violation';
  END IF;

  -- 1) Ownership-validated recovery.
  SELECT u.id INTO v_id
  FROM auth.users u JOIN public.profiles p ON p.id = u.id
  WHERE lower(btrim(u.email)) = lower(v_email)
    AND (u.raw_app_meta_data ->> 'account_type') = 'DilMart_federated_customer'
    AND (u.raw_app_meta_data ->> 'origin') = 'DilMart_federated'
    AND (u.raw_user_meta_data ->> 'DilMart_user_id') = p_DilMart_user_id::text
    AND u.deleted_at IS NULL AND (u.banned_until IS NULL OR u.banned_until < now())
    AND p.role = 'customer'
  LIMIT 1;
  IF FOUND THEN
    RETURN QUERY SELECT v_id, NULL::TEXT; RETURN;
  END IF;

  -- 2) Email held by a non-owned account → collision, never reuse.
  SELECT u.id INTO v_other FROM auth.users u WHERE lower(btrim(u.email)) = lower(v_email) LIMIT 1;
  IF FOUND THEN
    RETURN QUERY SELECT NULL::UUID, 'IDENTITY_BLOCKED'::TEXT; RETURN;
  END IF;

  -- 3) Provision. Ownership metadata + federated_id are set AT insert so the reserved-domain trigger allows it.
  v_id := gen_random_uuid();
  INSERT INTO auth.users
    (id, instance_id, aud, role, email, encrypted_password, raw_app_meta_data, raw_user_meta_data,
     created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change,
     email_change_token_current, phone_change, phone_change_token, reauthentication_token)
  VALUES
    (v_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', v_email,
     encode(sha256((gen_random_uuid()::text)::bytea), 'hex'),   -- unusable password; login impossible, never logged
     jsonb_build_object('provider','email','providers', array['email'],
                        'account_type','DilMart_federated_customer','origin','DilMart_federated','federated_id', p_federated_id),
     jsonb_build_object('account_type','DilMart_federated_customer','DilMart_user_id', p_DilMart_user_id::text),
     now(), now(), '', '', '', '', '', '', '', '');

  RETURN QUERY SELECT v_id, NULL::TEXT;
  RETURN;

EXCEPTION WHEN unique_violation THEN
  -- Concurrent creation: re-run ownership recovery; reuse if it is now ours, else collision.
  SELECT u.id INTO v_id
  FROM auth.users u JOIN public.profiles p ON p.id = u.id
  WHERE lower(btrim(u.email)) = lower(v_email)
    AND (u.raw_user_meta_data ->> 'DilMart_user_id') = p_DilMart_user_id::text
    AND (u.raw_app_meta_data ->> 'origin') = 'DilMart_federated'
    AND p.role = 'customer'
  LIMIT 1;
  IF FOUND THEN RETURN QUERY SELECT v_id, NULL::TEXT; ELSE RETURN QUERY SELECT NULL::UUID, 'IDENTITY_BLOCKED'::TEXT; END IF;
  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.redeem_and_create_federated_session(p_code_hash text, p_state_hash text, p_family_id uuid, p_refresh_token_id uuid, p_refresh_token_hash text, p_access_jti uuid, p_device_hash text, p_expected_handoff_id uuid, p_expected_store_customer_id uuid, p_expected_linked_profile_id uuid, p_expected_dilmart_user_id uuid, p_expected_target_path text, p_request_id uuid)
 RETURNS TABLE(status text, error_code text, store_customer_id uuid, linked_profile_id uuid, dilmart_user_id uuid, target_path text, display_name text, session_version integer, refresh_expires_in_seconds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  c_refresh CONSTANT INTEGER := 2592000;  -- 30d, approved
  c_abs     CONSTANT INTEGER := 7776000;  -- 90d, approved
  v_h    public.DilMart_customer_handoffs%ROWTYPE;
  v_link public.store_linked_profiles%ROWTYPE;
  v_prole TEXT;
  v_now  TIMESTAMPTZ;
  v_abs  TIMESTAMPTZ;
  v_rexp TIMESTAMPTZ;
  v_rsecs INTEGER;
BEGIN
  SELECT * INTO v_h FROM public.DilMart_customer_handoffs WHERE code_hash = p_code_hash FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'ERROR','HANDOFF_INVALID',NULL::UUID,NULL::UUID,NULL::UUID,NULL::TEXT,NULL::TEXT,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;
  IF v_h.state_hash IS DISTINCT FROM p_state_hash AND v_h.redeemed_at IS NULL THEN
    RETURN QUERY SELECT 'ERROR','HANDOFF_STATE_MISMATCH',NULL::UUID,NULL::UUID,NULL::UUID,NULL::TEXT,NULL::TEXT,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;
  IF v_h.redeemed_at IS NOT NULL THEN
    RETURN QUERY SELECT 'ERROR','HANDOFF_ALREADY_REDEEMED',NULL::UUID,NULL::UUID,NULL::UUID,NULL::TEXT,NULL::TEXT,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;
  IF v_h.expires_at <= clock_timestamp() THEN
    RETURN QUERY SELECT 'ERROR','HANDOFF_EXPIRED',NULL::UUID,NULL::UUID,NULL::UUID,NULL::TEXT,NULL::TEXT,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;
  IF v_h.identity_outcome <> 'LINKED' OR v_h.linked_profile_id IS NULL OR v_h.store_customer_id IS NULL THEN
    RETURN QUERY SELECT 'ERROR','HANDOFF_INVALID',NULL::UUID,NULL::UUID,NULL::UUID,NULL::TEXT,NULL::TEXT,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;

  -- B6: the context the caller pre-signed the access token for must still match the locked handoff, EXACTLY.
  IF v_h.id                IS DISTINCT FROM p_expected_handoff_id
     OR v_h.store_customer_id IS DISTINCT FROM p_expected_store_customer_id
     OR v_h.linked_profile_id IS DISTINCT FROM p_expected_linked_profile_id
     OR v_h.DilMart_user_id    IS DISTINCT FROM p_expected_DilMart_user_id
     OR v_h.target_path       IS DISTINCT FROM p_expected_target_path THEN
    RETURN QUERY SELECT 'ERROR','HANDOFF_CONTEXT_MISMATCH',NULL::UUID,NULL::UUID,NULL::UUID,NULL::TEXT,NULL::TEXT,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;

  -- Recheck the link + customer are still LINKED and Customer-compatible under lock.
  SELECT * INTO v_link FROM public.store_linked_profiles WHERE id = v_h.linked_profile_id FOR UPDATE;
  IF NOT FOUND
     OR upper(coalesce(v_link.DilMart_role,'')) <> 'CUSTOMER'
     OR upper(coalesce(v_link.link_status,'')) <> 'LINKED'
     OR v_link.store_customer_id IS DISTINCT FROM v_h.store_customer_id THEN
    RETURN QUERY SELECT 'ERROR','IDENTITY_BLOCKED',NULL::UUID,NULL::UUID,NULL::UUID,NULL::TEXT,NULL::TEXT,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;
  SELECT role INTO v_prole FROM public.profiles WHERE id = v_h.store_customer_id;
  IF v_prole IS DISTINCT FROM 'customer' THEN
    RETURN QUERY SELECT 'ERROR','IDENTITY_BLOCKED',NULL::UUID,NULL::UUID,NULL::UUID,NULL::TEXT,NULL::TEXT,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;

  -- Consume the handoff.
  UPDATE public.DilMart_customer_handoffs
     SET redeemed_at = clock_timestamp(), status = 'REDEEMED', updated_at = now()
   WHERE id = v_h.id;

  v_now  := clock_timestamp();
  v_abs  := v_now + make_interval(secs => c_abs);
  v_rexp := LEAST(v_now + make_interval(secs => c_refresh), v_abs);
  v_rsecs := GREATEST(0, floor(extract(epoch FROM (v_rexp - v_now))))::INTEGER;

  INSERT INTO public.store_federated_session_families
    (id, store_customer_id, linked_profile_id, DilMart_user_id, device_id_hash, session_version, status,
     last_used_at, absolute_expires_at, refresh_window_started_at, refresh_count, created_at, updated_at)
  VALUES
    (p_family_id, v_h.store_customer_id, v_h.linked_profile_id, v_h.DilMart_user_id, p_device_hash, 1, 'ACTIVE',
     v_now, v_abs, v_now, 0, v_now, v_now);

  INSERT INTO public.store_federated_refresh_tokens
    (id, session_family_id, token_hash, parent_token_id, expires_at, created_at)
  VALUES
    (p_refresh_token_id, p_family_id, p_refresh_token_hash, NULL, v_rexp, v_now);

  UPDATE public.store_linked_profiles SET last_handoff_at = clock_timestamp(), updated_at = now() WHERE id = v_link.id;

  INSERT INTO public.DilMart_customer_handoff_audit_events
    (request_id, handoff_id, linked_profile_id, event_type, status, source_surface, campaign, metadata)
  VALUES
    (p_request_id, v_h.id, v_h.linked_profile_id, 'HANDOFF_REDEEMED', 'REDEEMED', v_h.source_surface, v_h.campaign,
     jsonb_build_object('sessionFamilyId', p_family_id));

  INSERT INTO public.store_federated_session_audit_events
    (request_id, session_family_id, refresh_token_id, handoff_id, linked_profile_id, store_customer_id, event_type, status, metadata)
  VALUES
    (p_request_id, p_family_id, p_refresh_token_id, v_h.id, v_h.linked_profile_id, v_h.store_customer_id,
     'FEDERATED_SESSION_CREATED', 'ACTIVE', jsonb_build_object('accessJti', p_access_jti));

  RETURN QUERY SELECT 'OK', NULL::TEXT, v_h.store_customer_id, v_h.linked_profile_id, v_h.DilMart_user_id,
                      v_h.target_path, v_link.display_name, 1, v_rsecs;
  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.redeem_barber_handoff_and_create_session(p_code_hash text, p_state_hash text, p_session_token_hash text, p_session_ttl_seconds integer)
 RETURNS TABLE(outcome_status text, error_code text, handoff_id uuid, linked_profile_id uuid, dilmart_user_id uuid, dilmart_barbershop_id uuid, role text, display_name text, target_path text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_row     public.DilMart_barber_handoffs%ROWTYPE;
  v_profile public.store_linked_profiles%ROWTYPE;
BEGIN
  IF p_session_ttl_seconds IS NULL OR p_session_ttl_seconds < 300 OR p_session_ttl_seconds > 86400 THEN
    RAISE EXCEPTION 'barber web session ttl out of bounds' USING ERRCODE = 'check_violation';
  END IF;
  IF p_session_token_hash IS NULL OR length(p_session_token_hash) <> 64 THEN
    RAISE EXCEPTION 'barber web session token hash must be sha256 hex' USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.DilMart_barber_handoffs h
     SET redeemed_at = clock_timestamp(),
         status = 'REDEEMED',
         updated_at = now()
   WHERE h.code_hash = p_code_hash
     AND h.redeemed_at IS NULL
     AND h.status = 'PENDING'
     AND h.expires_at > clock_timestamp()
     AND h.state_hash = p_state_hash
  RETURNING h.* INTO v_row;

  IF FOUND THEN
    SELECT * INTO v_profile FROM public.store_linked_profiles
     WHERE id = v_row.linked_profile_id FOR UPDATE;
    -- Fail closed WITHOUT consuming: raising rolls back the consume above, so a corrupted /
    -- concurrently-mutated profile row never burns a valid code. A NULL DilMart_barbershop_id
    -- (legacy/partial row) is included here explicitly — without it the NOT NULL session insert
    -- below would raise an unclassified 23502 instead of this deliberate check_violation.
    IF NOT FOUND
       OR upper(coalesce(v_profile.DilMart_role, '')) NOT IN ('OWNER', 'BARBER')
       OR v_profile.DilMart_barbershop_id IS NULL THEN
      RAISE EXCEPTION 'barber handoff linked profile is not a complete Barber/Owner identity'
        USING ERRCODE = 'check_violation';
    END IF;

    -- Single-active-session: every prior ACTIVE session for this user dies with this redeem.
    -- Aliased + qualified: `DilMart_user_id` is also a RETURNS TABLE output name; unqualified it
    -- is ambiguous (42702) under plpgsql.variable_conflict = error.
    UPDATE public.DilMart_barber_web_sessions s
       SET status = 'REVOKED', revoked_at = clock_timestamp()
     WHERE s.DilMart_user_id = v_profile.DilMart_user_id
       AND s.status = 'ACTIVE';

    INSERT INTO public.DilMart_barber_web_sessions
      (session_token_hash, linked_profile_id, DilMart_user_id, DilMart_barbershop_id, role, expires_at)
    VALUES
      (p_session_token_hash, v_profile.id, v_profile.DilMart_user_id, v_profile.DilMart_barbershop_id,
       upper(v_profile.DilMart_role), clock_timestamp() + make_interval(secs => p_session_ttl_seconds));

    INSERT INTO public.DilMart_barber_handoff_audit_events
      (handoff_id, linked_profile_id, event_type, status, source_surface, metadata)
    VALUES
      (v_row.id, v_row.linked_profile_id, 'HANDOFF_REDEEMED', 'REDEEMED', v_row.source_surface, '{}'::jsonb);

    RETURN QUERY SELECT
      'REDEEMED', NULL::TEXT, v_row.id, v_profile.id, v_profile.DilMart_user_id,
      v_profile.DilMart_barbershop_id, upper(v_profile.DilMart_role), v_profile.display_name,
      v_row.target_path;
    RETURN;
  END IF;

  SELECT * INTO v_row FROM public.DilMart_barber_handoffs WHERE code_hash = p_code_hash;

  IF NOT FOUND THEN
    RETURN QUERY SELECT 'ERROR', 'HANDOFF_INVALID', NULL::UUID, NULL::UUID, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::TEXT;
  ELSIF v_row.state_hash IS DISTINCT FROM p_state_hash AND v_row.redeemed_at IS NULL THEN
    RETURN QUERY SELECT 'ERROR', 'HANDOFF_STATE_MISMATCH', NULL::UUID, NULL::UUID, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::TEXT;
  ELSIF v_row.redeemed_at IS NOT NULL THEN
    RETURN QUERY SELECT 'ERROR', 'HANDOFF_ALREADY_REDEEMED', NULL::UUID, NULL::UUID, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::TEXT;
  ELSIF v_row.expires_at <= clock_timestamp() THEN
    RETURN QUERY SELECT 'ERROR', 'HANDOFF_EXPIRED', NULL::UUID, NULL::UUID, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::TEXT;
  ELSE
    RETURN QUERY SELECT 'ERROR', 'HANDOFF_INVALID', NULL::UUID, NULL::UUID, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT, NULL::TEXT;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.redeem_customer_handoff(p_code_hash text, p_state_hash text)
 RETURNS TABLE(outcome_status text, error_code text, handoff_id uuid, linked_profile_id uuid, store_customer_id uuid, dilmart_user_id uuid, target_path text, identity_outcome text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_row public.DilMart_customer_handoffs%ROWTYPE;
  v_event TEXT;
BEGIN
  UPDATE public.DilMart_customer_handoffs h
     SET redeemed_at = clock_timestamp(),
         status = CASE WHEN h.identity_outcome = 'LINKED' THEN 'REDEEMED' ELSE h.status END,
         updated_at = now()
   WHERE h.code_hash = p_code_hash
     AND h.redeemed_at IS NULL
     AND h.status IN ('PENDING','LINK_REQUIRED','BLOCKED')
     AND h.expires_at > clock_timestamp()
     AND h.state_hash = p_state_hash
  RETURNING h.* INTO v_row;

  IF FOUND THEN
    -- Exactly ONE correctly-typed audit event per consumed outcome (task B5).
    v_event := CASE v_row.identity_outcome
                 WHEN 'LINKED'        THEN 'HANDOFF_REDEEMED'
                 WHEN 'LINK_REQUIRED' THEN 'HANDOFF_REDEEM_LINK_REQUIRED'
                 WHEN 'BLOCKED'       THEN 'HANDOFF_REDEEM_BLOCKED'
               END;
    INSERT INTO public.DilMart_customer_handoff_audit_events
      (handoff_id, linked_profile_id, event_type, status, source_surface, campaign, metadata)
    VALUES
      (v_row.id, v_row.linked_profile_id, v_event, v_row.identity_outcome,
       v_row.source_surface, v_row.campaign, '{}'::jsonb);

    RETURN QUERY SELECT
      CASE v_row.identity_outcome WHEN 'LINKED' THEN 'REDEEMED' ELSE v_row.identity_outcome END,
      NULL::TEXT,
      v_row.id, v_row.linked_profile_id, v_row.store_customer_id,
      v_row.DilMart_user_id, v_row.target_path, v_row.identity_outcome;
    RETURN;
  END IF;

  SELECT * INTO v_row FROM public.DilMart_customer_handoffs WHERE code_hash = p_code_hash;

  IF NOT FOUND THEN
    RETURN QUERY SELECT 'ERROR', 'HANDOFF_INVALID', NULL::UUID, NULL::UUID, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT;
  ELSIF v_row.state_hash IS DISTINCT FROM p_state_hash AND v_row.redeemed_at IS NULL THEN
    RETURN QUERY SELECT 'ERROR', 'HANDOFF_STATE_MISMATCH', NULL::UUID, NULL::UUID, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT;
  ELSIF v_row.redeemed_at IS NOT NULL THEN
    RETURN QUERY SELECT 'ERROR', 'HANDOFF_ALREADY_REDEEMED', NULL::UUID, NULL::UUID, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT;
  ELSIF v_row.expires_at <= clock_timestamp() THEN
    RETURN QUERY SELECT 'ERROR', 'HANDOFF_EXPIRED', NULL::UUID, NULL::UUID, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT;
  ELSE
    RETURN QUERY SELECT 'ERROR', 'HANDOFF_INVALID', NULL::UUID, NULL::UUID, NULL::UUID, NULL::UUID, NULL::TEXT, NULL::TEXT;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_reserved_federated_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_fed_id        TEXT;
  v_expected_email TEXT;
BEGIN
  IF NEW.email IS NULL OR lower(btrim(NEW.email)) NOT LIKE '%@federated.DilMart.internal' THEN
    RETURN NEW;  -- not a reserved-domain row → unaffected
  END IF;

  v_fed_id := NEW.raw_app_meta_data ->> 'federated_id';

  IF (NEW.raw_app_meta_data ->> 'account_type') IS DISTINCT FROM 'DilMart_federated_customer'
     OR (NEW.raw_app_meta_data ->> 'origin') IS DISTINCT FROM 'DilMart_federated'
     OR v_fed_id IS NULL
     OR (NEW.raw_user_meta_data ->> 'DilMart_user_id') IS NULL
     OR (NEW.raw_user_meta_data ->> 'DilMart_user_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  THEN
    RAISE EXCEPTION 'The federated.DilMart.internal domain requires complete federation ownership metadata.';
  END IF;

  v_expected_email := 'DilMart-federated+' || v_fed_id || '@federated.DilMart.internal';
  IF lower(btrim(NEW.email)) IS DISTINCT FROM lower(v_expected_email) THEN
    RAISE EXCEPTION 'Reserved federated email does not match its federated_id.';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.revoke_federated_sessions_for_identity(p_dilmart_user_id uuid, p_linked_profile_id uuid, p_reason text, p_request_id uuid)
 RETURNS TABLE(revoked_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r RECORD; v_n INTEGER := 0;
BEGIN
  IF p_DilMart_user_id IS NULL AND p_linked_profile_id IS NULL THEN
    RAISE EXCEPTION 'an identity key is required' USING ERRCODE = 'check_violation';
  END IF;
  FOR r IN
    SELECT id, linked_profile_id, store_customer_id FROM public.store_federated_session_families
     WHERE status = 'ACTIVE'
       AND (p_DilMart_user_id    IS NULL OR DilMart_user_id    = p_DilMart_user_id)
       AND (p_linked_profile_id IS NULL OR linked_profile_id = p_linked_profile_id)
     ORDER BY id
     FOR UPDATE
  LOOP
    UPDATE public.store_federated_session_families
       SET status = 'REVOKED', revoked_at = clock_timestamp(), revoke_reason = COALESCE(p_reason,'INTERNAL_REVOKE'),
           session_version = store_federated_session_families.session_version + 1, updated_at = now()
     WHERE id = r.id;
    UPDATE public.store_federated_refresh_tokens SET revoked_at = clock_timestamp()
      WHERE session_family_id = r.id AND revoked_at IS NULL;
    INSERT INTO public.store_federated_session_audit_events
      (request_id, session_family_id, linked_profile_id, store_customer_id, event_type, status, error_code)
    VALUES (p_request_id, r.id, r.linked_profile_id, r.store_customer_id, 'FEDERATED_SESSION_REVOKED', 'REVOKED', p_reason);
    v_n := v_n + 1;
  END LOOP;
  RETURN QUERY SELECT v_n; RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.rotate_federated_refresh_token(p_current_token_hash text, p_new_token_id uuid, p_new_token_hash text, p_device_hash text, p_expected_family_id uuid, p_expected_store_customer_id uuid, p_expected_linked_profile_id uuid, p_expected_dilmart_user_id uuid, p_expected_session_version integer, p_request_id uuid)
 RETURNS TABLE(status text, error_code text, family_id uuid, store_customer_id uuid, linked_profile_id uuid, dilmart_user_id uuid, session_version integer, refresh_expires_in_seconds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  c_refresh  CONSTANT INTEGER := 2592000;  -- 30d
  c_inactive CONSTANT INTEGER := 2592000;  -- 30d inactivity
  c_rate     CONSTANT INTEGER := 30;
  c_window   CONSTANT INTEGER := 3600;
  v_fam_id UUID;
  v_tok public.store_federated_refresh_tokens%ROWTYPE;
  v_fam public.store_federated_session_families%ROWTYPE;
  v_link public.store_linked_profiles%ROWTYPE;
  v_prole TEXT;
  v_now TIMESTAMPTZ;
  v_new_exp TIMESTAMPTZ;
  v_rsecs INTEGER;
BEGIN
  -- (1) Read token → family id WITHOUT a row lock.
  SELECT session_family_id INTO v_fam_id FROM public.store_federated_refresh_tokens WHERE token_hash = p_current_token_hash;
  IF v_fam_id IS NULL THEN
    RETURN QUERY SELECT 'ERROR','FEDERATED_SESSION_EXPIRED',NULL::UUID,NULL::UUID,NULL::UUID,NULL::UUID,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;

  -- (2) Lock the family FIRST (deterministic order → no deadlock across lifecycle RPCs).
  SELECT * INTO v_fam FROM public.store_federated_session_families WHERE id = v_fam_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'ERROR','FEDERATED_SESSION_EXPIRED',NULL::UUID,NULL::UUID,NULL::UUID,NULL::UUID,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;

  -- (3) Lock the exact token row. (4) Revalidate it still belongs to the locked family.
  SELECT * INTO v_tok FROM public.store_federated_refresh_tokens WHERE token_hash = p_current_token_hash FOR UPDATE;
  IF NOT FOUND OR v_tok.session_family_id IS DISTINCT FROM v_fam.id THEN
    RETURN QUERY SELECT 'ERROR','FEDERATED_SESSION_EXPIRED',NULL::UUID,NULL::UUID,NULL::UUID,NULL::UUID,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;

  -- REUSE DETECTION (precedes everything else). A used token presented again compromises the family.
  IF v_tok.used_at IS NOT NULL THEN
    UPDATE public.store_federated_session_families
       SET status = 'COMPROMISED', revoked_at = clock_timestamp(), revoke_reason = 'REFRESH_REUSE',
           session_version = store_federated_session_families.session_version + 1, updated_at = now()
     WHERE id = v_fam.id;
    UPDATE public.store_federated_refresh_tokens
       SET revoked_at = clock_timestamp()
     WHERE session_family_id = v_fam.id AND revoked_at IS NULL;
    UPDATE public.store_federated_refresh_tokens SET reuse_detected_at = clock_timestamp() WHERE id = v_tok.id;
    INSERT INTO public.store_federated_session_audit_events
      (request_id, session_family_id, refresh_token_id, linked_profile_id, store_customer_id, event_type, status, error_code)
    VALUES (p_request_id, v_fam.id, v_tok.id, v_fam.linked_profile_id, v_fam.store_customer_id,
            'FEDERATED_REFRESH_REUSE_DETECTED', 'COMPROMISED', 'FEDERATED_REFRESH_REUSE_DETECTED');
    RETURN QUERY SELECT 'ERROR','FEDERATED_REFRESH_REUSE_DETECTED',NULL::UUID,NULL::UUID,NULL::UUID,NULL::UUID,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;

  -- Token/family validity (fail closed; no enumeration oracle → all map to FEDERATED_SESSION_EXPIRED).
  IF v_tok.revoked_at IS NOT NULL
     OR v_tok.expires_at <= clock_timestamp()
     OR v_fam.status <> 'ACTIVE'
     OR v_fam.revoked_at IS NOT NULL
     OR v_fam.absolute_expires_at <= clock_timestamp()
     OR (v_fam.last_used_at + make_interval(secs => c_inactive)) <= clock_timestamp() THEN
    IF v_fam.status = 'ACTIVE'
       AND (v_fam.absolute_expires_at <= clock_timestamp()
            OR (v_fam.last_used_at + make_interval(secs => c_inactive)) <= clock_timestamp()) THEN
      UPDATE public.store_federated_session_families SET status = 'EXPIRED', updated_at = now() WHERE id = v_fam.id;
      UPDATE public.store_federated_refresh_tokens SET revoked_at = clock_timestamp()
        WHERE session_family_id = v_fam.id AND revoked_at IS NULL;
      INSERT INTO public.store_federated_session_audit_events
        (request_id, session_family_id, refresh_token_id, linked_profile_id, store_customer_id, event_type, status, error_code)
      VALUES (p_request_id, v_fam.id, v_tok.id, v_fam.linked_profile_id, v_fam.store_customer_id,
              'FEDERATED_SESSION_EXPIRED', 'EXPIRED', 'FEDERATED_SESSION_EXPIRED');
    END IF;
    RETURN QUERY SELECT 'ERROR','FEDERATED_SESSION_EXPIRED',NULL::UUID,NULL::UUID,NULL::UUID,NULL::UUID,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;

  -- B6: the pre-signed access-token context must match the locked family EXACTLY (incl. session_version).
  IF v_fam.id                IS DISTINCT FROM p_expected_family_id
     OR v_fam.store_customer_id IS DISTINCT FROM p_expected_store_customer_id
     OR v_fam.linked_profile_id IS DISTINCT FROM p_expected_linked_profile_id
     OR v_fam.DilMart_user_id    IS DISTINCT FROM p_expected_DilMart_user_id
     OR v_fam.session_version   IS DISTINCT FROM p_expected_session_version THEN
    RETURN QUERY SELECT 'ERROR','FEDERATED_SESSION_EXPIRED',NULL::UUID,NULL::UUID,NULL::UUID,NULL::UUID,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;

  -- Device binding: a bound family requires the same device hash at refresh.
  IF v_fam.device_id_hash IS NOT NULL AND v_fam.device_id_hash IS DISTINCT FROM p_device_hash THEN
    RETURN QUERY SELECT 'ERROR','FEDERATED_SESSION_EXPIRED',NULL::UUID,NULL::UUID,NULL::UUID,NULL::UUID,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;

  -- Link/customer still LINKED + Customer-compatible.
  SELECT * INTO v_link FROM public.store_linked_profiles WHERE id = v_fam.linked_profile_id;
  IF NOT FOUND OR upper(coalesce(v_link.DilMart_role,'')) <> 'CUSTOMER' OR upper(coalesce(v_link.link_status,'')) <> 'LINKED' THEN
    RETURN QUERY SELECT 'ERROR','FEDERATED_SESSION_EXPIRED',NULL::UUID,NULL::UUID,NULL::UUID,NULL::UUID,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;
  SELECT role INTO v_prole FROM public.profiles WHERE id = v_fam.store_customer_id;
  IF v_prole IS DISTINCT FROM 'customer' THEN
    RETURN QUERY SELECT 'ERROR','FEDERATED_SESSION_EXPIRED',NULL::UUID,NULL::UUID,NULL::UUID,NULL::UUID,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;

  -- RATE LIMIT (DB fixed window, under the family lock). Reset the window if elapsed.
  IF (v_fam.refresh_window_started_at + make_interval(secs => c_window)) <= clock_timestamp() THEN
    UPDATE public.store_federated_session_families
       SET refresh_window_started_at = clock_timestamp(), refresh_count = 0, updated_at = now()
     WHERE id = v_fam.id;
    v_fam.refresh_count := 0;
  END IF;
  IF v_fam.refresh_count >= c_rate THEN
    RETURN QUERY SELECT 'ERROR','FEDERATED_REFRESH_RATE_LIMITED',NULL::UUID,NULL::UUID,NULL::UUID,NULL::UUID,NULL::INTEGER,NULL::INTEGER; RETURN;
  END IF;

  -- ROTATE. New token expiry may not extend beyond the family's absolute expiry.
  v_now := clock_timestamp();
  v_new_exp := LEAST(v_now + make_interval(secs => c_refresh), v_fam.absolute_expires_at);
  v_rsecs := GREATEST(0, floor(extract(epoch FROM (v_new_exp - v_now))))::INTEGER;

  -- Insert the child token FIRST so the old token's replaced_by_token_id FK is satisfiable.
  INSERT INTO public.store_federated_refresh_tokens
    (id, session_family_id, token_hash, parent_token_id, expires_at, created_at)
  VALUES (p_new_token_id, v_fam.id, p_new_token_hash, v_tok.id, v_new_exp, v_now);

  UPDATE public.store_federated_refresh_tokens
     SET used_at = clock_timestamp(), replaced_by_token_id = p_new_token_id
   WHERE id = v_tok.id;

  UPDATE public.store_federated_session_families
     SET last_used_at = clock_timestamp(), last_rotated_at = clock_timestamp(),
         refresh_count = refresh_count + 1, updated_at = now()
   WHERE id = v_fam.id;

  INSERT INTO public.store_federated_session_audit_events
    (request_id, session_family_id, refresh_token_id, linked_profile_id, store_customer_id, event_type, status)
  VALUES (p_request_id, v_fam.id, p_new_token_id, v_fam.linked_profile_id, v_fam.store_customer_id,
          'FEDERATED_SESSION_REFRESHED', 'ACTIVE');

  RETURN QUERY SELECT 'OK', NULL::TEXT, v_fam.id, v_fam.store_customer_id, v_fam.linked_profile_id,
                      v_fam.DilMart_user_id, v_fam.session_version, v_rsecs;
  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_federated_session_family(p_family_id uuid, p_session_version integer)
 RETURNS TABLE(valid boolean, store_customer_id uuid, linked_profile_id uuid, dilmart_user_id uuid, session_version integer, email text, phone text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  c_inactive CONSTANT INTEGER := 2592000;  -- 30d
  v_fam public.store_federated_session_families%ROWTYPE;
  v_link public.store_linked_profiles%ROWTYPE;
  v_prole TEXT; v_email TEXT; v_phone TEXT;
BEGIN
  SELECT * INTO v_fam FROM public.store_federated_session_families WHERE id = p_family_id;
  IF NOT FOUND
     OR v_fam.status <> 'ACTIVE'
     OR v_fam.session_version <> p_session_version
     OR v_fam.revoked_at IS NOT NULL
     OR v_fam.absolute_expires_at <= clock_timestamp()
     OR (v_fam.last_used_at + make_interval(secs => c_inactive)) <= clock_timestamp() THEN
    RETURN QUERY SELECT FALSE, NULL::UUID, NULL::UUID, NULL::UUID, NULL::INTEGER, NULL::TEXT, NULL::TEXT; RETURN;
  END IF;

  SELECT * INTO v_link FROM public.store_linked_profiles WHERE id = v_fam.linked_profile_id;
  IF NOT FOUND OR upper(coalesce(v_link.DilMart_role,'')) <> 'CUSTOMER' OR upper(coalesce(v_link.link_status,'')) <> 'LINKED' THEN
    RETURN QUERY SELECT FALSE, NULL::UUID, NULL::UUID, NULL::UUID, NULL::INTEGER, NULL::TEXT, NULL::TEXT; RETURN;
  END IF;

  SELECT p.role, p.email, p.phone INTO v_prole, v_email, v_phone FROM public.profiles p WHERE p.id = v_fam.store_customer_id;
  IF v_prole IS DISTINCT FROM 'customer' THEN
    RETURN QUERY SELECT FALSE, NULL::UUID, NULL::UUID, NULL::UUID, NULL::INTEGER, NULL::TEXT, NULL::TEXT; RETURN;
  END IF;

  RETURN QUERY SELECT TRUE, v_fam.store_customer_id, v_fam.linked_profile_id, v_fam.DilMart_user_id, v_fam.session_version, v_email, v_phone;
  RETURN;
END;
$function$

